messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Humanoid Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #222; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x333333);

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(4, 2, 0);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(5, 10, 5);
        scene.add(dirLight);

        // --- Ground (Treadmill) ---
        const groundGeo = new THREE.BoxGeometry(6, 0.2, 3);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x444444 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        scene.add(ground);

        // --- Humanoid Construction ---
        const group = new THREE.Group();
        const mat = new THREE.MeshStandardMaterial({ color: 0x00ffcc });

        const createBox = (w, h, d, x, y, z) => {
            const geo = new THREE.BoxGeometry(w, h, d);
            const mesh = new THREE.Mesh(geo, mat);
            mesh.position.set(x, y, z);
            return mesh;
        };

        const torso = createBox(0.6, 0.8, 0.3, 0, 1.4, 0);
        const head = createBox(0.3, 0.3, 0.3, 0, 2.0, 0);

        // Limbs
        const leftLeg = new THREE.Group();
        const lLegMesh = createBox(0.2, 0.7, 0.2, 0, -0.35, 0);
        leftLeg.add(lLegMesh);
        leftLeg.position.set(-0.2, 1.0, 0);

        const rightLeg = new THREE.Group();
        const rLegMesh = createBox(0.2, 0.7, 0.2, 0, -0.35, 0);
        rightLeg.add(rLegMesh);
        rightLeg.position.set(0.2, 1.0, 0);

        const leftArm = new THREE.Group();
        const lArmMesh = createBox(0.2, 0.7, 0.2, 0, -0.35, 0);
        leftArm.add(lArmMesh);
        leftArm.position.set(-0.4, 1.7, 0);

        const rightArm = new THREE.Group();
        const rArmMesh = createBox(0.2, 0.7, 0.2, 0, -0.35, 0);
        rightArm.add(rArmMesh);
        rightArm.position.set(0.4, 1.7, 0);

        group.add(torso, head, leftLeg, rightLeg, leftArm, rightArm);
        scene.add(group);

        // --- Animation Logic ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);
            const t = clock.getElapsedTime();
            const cycleTime = t % 10; // 10 second loop

            let swingAngle = 0;
            let swingSpeed = 0;
            let lean = 0;

            if (cycleTime < 2) {
                // Stand still (0-2s)
                swingAngle = 0;
                lean = 0;
            } else if (cycleTime < 5) {
                // Walk (2-5s)
                swingSpeed = 4; 
                swingAngle = Math.sin(t * swingSpeed) * 0.4;
                lean = 0.05;
            } else if (cycleTime < 8) {
                // Run (5-8s)
                swingSpeed = 8;
                swingAngle = Math.sin(t * swingSpeed) * 0.8;
                lean = 0.2;
            } else {
                // Stand still (8-10s)
                swingAngle = 0;
                lean = 0;
            }

            // Apply animations
            // Legs move opposite to each other
            leftLeg.rotation.z = swingAngle;
            rightLeg.rotation.z = -swingAngle;

            // Arms move opposite to legs
            leftArm.rotation.z = -swingAngle;
            rightArm.rotation.z = swingAngle;

            // Torso lean
            group.rotation.z = lean;

            // Subtle bounce for running/walking
            if (swingSpeed > 0) {
                group.position.y = Math.abs(Math.sin(t * swingSpeed * 2)) * 0.05;
            } else {
                group.position.y = 0;
            }

            renderer.render(scene, camera);
        }

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
